    {q:"Simplify: (2x) to the 3", options:["2x to the 3","6x to the 3","8x","8x to the 3"], answer:3},
    {q:"A fractional exponent such as x to the one half represents ___.", options:["x squared","x divided by 2","twice x","the square root of x"], answer:3},
    {q:"A population growing by 5 percent each year can be modelled using an exponential function with base ___.", options:["1.5","0.05","5","1.05"], answer:3}
