    {q:"An angle formed by two chords with a vertex on the circle itself is called an ___ angle.", options:["inscribed","exterior","tangent","central"], answer:0},
    {q:"An inscribed angle is always ___ the central angle that subtends the same arc.", options:["unrelated to","half of","equal to","double"], answer:1},
    {q:"An inscribed angle that subtends a semicircle always measures ___.", options:["180 degrees","45 degrees","90 degrees","60 degrees"], answer:2},
    {q:"Two tangent segments drawn to a circle from the same external point are always ___ in length.", options:["equal","different","proportional to the radius only","perpendicular"], answer:0},
    {q:"A polygon with all vertices on a circle is called a ___ polygon.", options:["tangent","convex","cyclic","regular"], answer:2},
    {q:"The portion of a circle between a chord and the arc it subtends is called a ___.", options:["segment","radius","sector","tangent line"], answer:0}
